# Wait, let's also read extra primes from expand_out.txt
import re
with open("/workspace/leanproject/Submission/expand_out.txt") as f:
    content = f.read()
match = re.search(r"Extra primes:\s*(\[.*\])", content)
if match:
    extra_primes_str = match.group(1)
    try:
        extra_primes = eval(extra_primes_str)
    except Exception:
        pairs = re.findall(r"\((\d+),?\s*(\d+)\)", extra_primes_str)
        extra_primes = [(int(p), int(r)) for p, r in pairs]
    for p, _ in extra_primes:
        primes.append(p)

# We want to check if for ANY (s, i) where s >= 40 or i >= 160:
# Is it possible that n0_sq - v is NOT blocked?
# Wait! Since fs * 4^i < N^2 can be huge, we can check a few values of s and i to see if they are blocked.
# Actually, let's check s in range(40, 200) and i in range(160, 400).
# Let's see if any is unblocked.
unblocked = []
for s in range(40, 100):
    fs = (10 * 16**s + 16 * 4**s + 10) // 9
    if fs >= N2:
        break
    for i in range(0, 200):
        v = fs * 4**i
        if v >= N2:
            break
        val = N2 - v
        blocked = False
        for p in primes:
            if val % p == 0 and val % (p*p) != 0:
                blocked = True
                break
        if not blocked:
            unblocked.append((s, i, v))
            if len(unblocked) > 5:
                break
    if len(unblocked) > 5:
        break

print("Unblocked cases found for s >= 40:", unblocked)
